  Future<void> _transferAction(
    InventoryTransfer transfer,
    String action,
  ) async {
    final completesInternalTransfer = _managesTransferInternally(transfer) &&
        ((action == 'approve' &&
                transfer.status == InventoryTransferStatus.requested) ||
            (action == 'dispatch' &&
                transfer.status == InventoryTransferStatus.approved));
    final labels = {
      'approve': 'Transferni tasdiqlaysizmi?',
      'reject': 'Transferni rad qilasizmi?',
      'dispatch': 'Mahsulot jo‘natildimi?',
      'receive': 'Mahsulot to‘liq qabul qilindimi?',
      'accept_preparation': 'Seriyoni tayyorlov sarfiga qabul qilasizmi?',
      'cancel': 'Transfer bekor qilinsinmi?',
    };
    final positionCount = action == 'accept_preparation'
        ? transfer.pendingPreparationLots
        : transfer.lines.length;
    final confirmed = await showDialog<bool>(
          context: context,
          builder: (context) => AlertDialog(
            title: Text(
              completesInternalTransfer
                  ? 'Ichki ko‘chirishni yakunlaysizmi?'
                  : labels[action] ?? 'Transfer',
            ),
            content: UrduAwareText(
              '${transfer.sourceWarehouse} → '
              '${transfer.destinationWarehouse}\n'
              '$positionCount ta pozitsiya',
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context, false),
                child: const UrduAwareText('Yo‘q'),
              ),
              FilledButton(
                onPressed: () => Navigator.pop(context, true),
                child: const UrduAwareText('Ha'),
              ),
            ],
          ),
        ) ??
        false;
    if (!confirmed || !mounted) {
      return;
    }
    await _runBusy('${transfer.id}:$action', () async {
      if (action == 'accept_preparation') {
        await MobileApi.instance.preparationAcceptTransfer(transfer.id);
        if (!mounted) return;
        final history = _preparationHistoryTabKey.currentState;
        await Future.wait([
          _loadPendingPreparationTransfers(force: true),
          _loadAssets(force: true),
          if (history != null) history._load(),
        ]);
        if (mounted) _showMessage('Seriyo tayyorlov sarfiga qabul qilindi');
        return;
      }
      final updated = await MobileApi.instance.inventoryTransferAction(
        transferId: transfer.id,
        action: action,
        idempotencyKey: _idempotencyKey(action),
      );
      _upsertTransfer(updated);
      await _applyAssetMutations(_assetMutationsForTransfer(updated));
      await _preparationHistoryTabKey.currentState?._load();
    });
  }
